pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }
    function testRegression_property() public {
        address dummyToken = address(new AlwaysRevertToken());

        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint[] memory amounts = new uint[](1);
        amounts[0] = 100;

        bool ok;
        try c.transfer(from, dummyToken, tos, amounts) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false, "Reference should revert");
    }
}

contract AlwaysRevertToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("always revert");
    }
}
